import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.DhF4LrUq.js";const s="/shipperdog/snapshot/screenshots/console-channels.png",u=JSON.parse('{"title":"Set up distribution channels","description":"Set up distribution channels - the channel catalog, the store-account credential chain from organization to app to environment, and the store-side metadata.","frontmatter":{"description":"Set up distribution channels - the channel catalog, the store-account credential chain from organization to app to environment, and the store-side metadata."},"headers":[],"relativePath":"how-to/console/distribution-channels.md","filePath":"how-to/console/distribution-channels.md"}'),r={name:"how-to/console/distribution-channels.md"};function i(l,e,c,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="set-up-distribution-channels" tabindex="-1">Set up distribution channels <a class="header-anchor" href="#set-up-distribution-channels" aria-label="Permalink to &quot;Set up distribution channels&quot;">​</a></h1><p>The <strong>Distribution channels</strong> screen is where store distribution becomes real: the channel catalog tells you which adapters exist, and the credential-delegation chain decides which store account a release&#39;s dispatches use — with App Store and Google Play both supported.</p><p><img src="'+s+'" alt="The Distribution channels screen"></p><p>How dispatch resolves a channel and its credentials is covered in <a href="/shipperdog/snapshot/concepts/security-model">the security model</a>.</p><h2 id="read-the-channel-catalog" tabindex="-1">Read the channel catalog <a class="header-anchor" href="#read-the-channel-catalog" aria-label="Permalink to &quot;Read the channel catalog&quot;">​</a></h2><p>The first table lists the registered channel adapters — their display names, capabilities, credential providers, and descriptions. The catalog is read-only: the registry owns these facts. What you own is the accounts their dispatches resolve.</p><h2 id="bind-a-store-account-the-delegation-chain" tabindex="-1">Bind a store account (the delegation chain) <a class="header-anchor" href="#bind-a-store-account-the-delegation-chain" aria-label="Permalink to &quot;Bind a store account (the delegation chain)&quot;">​</a></h2><p>Secret material enters exactly once, through the bind dialog, and is never echoed again — the table carries only the opaque <em>secret reference</em> the account resolves through.</p><ol><li><p>Click <strong>Bind store account</strong>.</p></li><li><p>Choose the <strong>Level</strong> — the heart of the delegation chain:</p><ul><li><strong>Organization (the inherited default)</strong> — every application and environment in the organization inherits this account.</li><li><strong>Application override</strong> — pick the application; its dispatches use this account regardless of the organization default.</li><li><strong>Application + environment override</strong> — pick both; the most specific binding wins.</li></ul><p>Resolution walks <strong>environment → application → organization</strong>: the first defined binding along that walk is the one used.</p></li><li><p>Fill in the <strong>Provider</strong> — the store&#39;s vocabulary: <code>apple</code>, <code>google-play</code> — an <strong>Account name</strong> for the table, and the <strong>Secret material</strong> itself (the field masks it): the API key or service-account credentials your store issued.</p></li><li><p>Bind. The row appears with its level chip and secret reference.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">Why the chain exists</p><p>One ASC key for the whole company, a separate one for the regulated app, a third for that app&#39;s production environment — without re-entering secrets per release. Bind the organization default first, then override only where a store account genuinely differs.</p></div><h2 id="verify-and-rotate" tabindex="-1">Verify and rotate <a class="header-anchor" href="#verify-and-rotate" aria-label="Permalink to &quot;Verify and rotate&quot;">​</a></h2><ul><li><strong>Verify</strong> on a binding answers exactly one question: does the secret reference still <em>resolve</em> through the secret store? Green means the credential is reachable — the store&#39;s own opinion of the credential surfaces when a dispatch uses it.</li><li><strong>Remove</strong> deletes the binding (the chain falls back to the next level). To rotate a credential, bind a new account at the same level and remove the old one.</li></ul><h2 id="app-store-listing-metadata" tabindex="-1">App Store listing metadata <a class="header-anchor" href="#app-store-listing-metadata" aria-label="Permalink to &quot;App Store listing metadata&quot;">​</a></h2><p>The <strong>App Store listing metadata</strong> section keeps the per-locale store facts a TestFlight/App Store dispatch can carry: pick the application and locale, then set the <strong>Description</strong>, <strong>Keywords</strong>, <strong>Screenshot references</strong>, and the <strong>Release notes (what&#39;s new)</strong> for that locale. Save per locale.</p><h2 id="google-play-release-notes" tabindex="-1">Google Play release notes <a class="header-anchor" href="#google-play-release-notes" aria-label="Permalink to &quot;Google Play release notes&quot;">​</a></h2><p>The <strong>Google Play release notes</strong> section holds the per-locale <em>what&#39;s new</em> text Play dispatches carry — pick the application and locale, write the notes, save.</p><h2 id="google-play-tester-tracks" tabindex="-1">Google Play tester tracks <a class="header-anchor" href="#google-play-tester-tracks" aria-label="Permalink to &quot;Google Play tester tracks&quot;">​</a></h2><p>The <strong>Google Play tester tracks</strong> section maps your tenants&#39; tester groups to Play tracks. Pick an application under <strong>Application tracks</strong> to see its Play tracks with Google&#39;s own status words (the store-side standing, live). Then <strong>Link a tester group to a Play track</strong> by picking the application, tenant, tester group, and the Play track. When a release dispatches (or a staged rollout widens), the mapped groups land on the mapped tracks.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/staged-rollout">staged rollout</a> · <a href="/shipperdog/snapshot/how-to/console/rings-and-promotion">rings and promotion</a> · <a href="/shipperdog/snapshot/concepts/security-model">security model concepts</a></p>',19)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
